#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptCount() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number. The mirror asks the client
// to wait a few seconds and retry, so a 429 is handled in-process: back
// off, log the new attempt (which advances the mirror's run number), and
// re-check only the packages that were limited. The check passes only once
// every package has resolved cleanly at least once. A hard time bound keeps
// a misbehaving mirror from hanging the publish.
const deadlineMs = 10 * 60 * 1000;

function sleepMs(ms) {
  const until = Date.now() + ms;
  while (Date.now() < until) {
    // synchronous sleep
  }
}

function verifyPackage(pkg, name) {
  const meta = JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
  if (meta.versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
    return true;
  }
  console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
    " not on mirror");
  return false;
}

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

const startTime = Date.now();
const verified = new Set();
const permanentlyFailed = new Set();

// Each pass logs one attempt (advancing the mirror's run number, which
// rotates the rate-limited package) and re-checks every package that has
// not yet resolved. A package that is 429 this pass is simply retried on
// a later pass; a package that 404s is a hard failure.
let pass = 0;
for (;;) {
  if (Date.now() - startTime > deadlineMs) {
    console.error("ERR! dependency check exceeded the 10 minute limit; " +
      "the registry mirror is not recovering, aborting");
    console.error("dependency check failed");
    process.exit(1);
  }
  pass++;
  const run = attemptCount();
  fs.appendFileSync(".attempts.log",
    new Date().toISOString() + " check " + (run + 1) + "\n");
  const limited = deps[run % deps.length];
  const remaining = deps.filter((n) =>
    !verified.has(n) && !permanentlyFailed.has(n));
  if (remaining.length === 0) {
    break;
  }
  for (const name of remaining) {
    if (name === limited) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror busy, retry in a few seconds)");
      continue;
    }
    if (verifyPackage(pkg, name)) {
      verified.add(name);
    } else {
      permanentlyFailed.add(name);
    }
  }
  if (permanentlyFailed.size > 0) {
    console.error("dependency check failed");
    process.exit(1);
  }
  const delayMs = 1500 + Math.random() * 1500;
  console.error("backing off for " + Math.round(delayMs) +
    " ms before attempt " + (run + 2) +
    " (elapsed " + Math.round((Date.now() - startTime) / 1000) + "s)");
  sleepMs(delayMs);
}

console.log("all dependencies resolve");

